// Normalize all sources into standard insight format
const now = new Date().toISOString();
const insights = [];

// Google Trends (response is JSONP-wrapped, strip 5 leading chars)
try {
  const trendsRaw = $('Google Trends VN').first().json;
  const cleaned = typeof trendsRaw === 'string' ? trendsRaw.replace(/^\)\]\}',?\n?/, '') : JSON.stringify(trendsRaw);
  const trends = JSON.parse(cleaned);
  const stories = trends?.default?.trendingSearchesDays?.[0]?.trendingSearches || [];
  for (const s of stories.slice(0, 15)) {
    const title = s.title?.query || '';
    if (!title) continue;
    insights.push({
      date: now,
      source: 'google_trends',
      raw_text: title + ' — ' + (s.articles?.[0]?.title || ''),
      topic_tag: ['trending', 'search'],
      audience_segment: ['general'],
      intent_level: Math.min(5, Math.ceil((s.formattedTraffic || '0').replace(/[^0-9]/g, '') / 50000) || 2),
    });
  }
} catch (e) { /* skip if parse failed */ }

// GHL form submissions — extract latest queries from contacts
try {
  const ghl = $('GHL: Recent Form Submissions').first().json;
  const contacts = ghl.contacts || [];
  for (const c of contacts.slice(0, 25)) {
    const text = [c.firstName, c.lastName, c.tags?.join(','), c.source].filter(Boolean).join(' | ');
    if (!text) continue;
    insights.push({
      date: now,
      source: 'ghl_form',
      raw_text: 'Form submission: ' + text + ' | locationId=' + ($env.GHL_LOCATION_ID || ''),
      topic_tag: c.tags || ['parent_interest'],
      audience_segment: c.tags || ['parent'],
      intent_level: 5,
    });
  }
} catch (e) {}

// FB owned comments
try {
  const fb = $('FB Page Owned Comments').first().json;
  const posts = fb.data || [];
  for (const post of posts) {
    const comments = post.comments?.data || [];
    for (const cm of comments.slice(0, 5)) {
      if (!cm.message || cm.message.length < 15) continue;
      insights.push({
        date: cm.created_time || now,
        source: 'owned_comments',
        raw_text: cm.message,
        topic_tag: ['fb_comment'],
        audience_segment: ['parent'],
        intent_level: 4,
      });
    }
  }
} catch (e) {}

return insights.map(i => ({ json: i }));

// Wrap batch into Airtable records array
const items = $input.all();
const records = items.map(item => ({ fields: item.json }));
return [{ json: { records, typecast: true } }];
